import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative, resolve, sep } from 'node:path';
import { STATIONS } from '@/content/types';

/**
 * fonts.css is generated by scripts/fonts/build-fonts.py (never hand-edited): these checks pin
 * the slicing contract the shell relies on — the UI glyph inventory lives in `base`, the brush
 * family ships no catch-all `rest` face, and every slice file on disk is one the stylesheet uses.
 */
const ROOT = process.cwd();
const css = readFileSync(resolve(ROOT, 'src/styles/fonts.css'), 'utf8');

interface Face {
  family: string;
  file: string;
  range: string;
}
type Span = [lo: number, hi: number];

const faces: Face[] = Array.from(css.matchAll(/@font-face \{([^}]*)\}/g), (m) => {
  const body = m[1]!;
  return {
    family: /font-family: "([^"]+)"/.exec(body)![1]!,
    file: /url\("\/fonts\/([^"]+)"\)/.exec(body)![1]!,
    range: /unicode-range: ([^;]+);/.exec(body)![1]!,
  };
});

const FAMILIES = ['DotGothic16', 'Yuji Syuku', 'Shippori Mincho B1', 'Dela Gothic One'];
const slice = (file: string): string => /-(base|n5|n4|n3|n2|rest)\.woff2$/.exec(file)![1]!;
const isLevel = (f: Face): boolean => /^n[2-5]$/.test(slice(f.file));
const byFamily = (family: string): Face[] => faces.filter((f) => f.family === family);
const spans = (range: string): Span[] =>
  range.split(',').map((part) => {
    const m = /U\+([0-9A-F]+)(?:-([0-9A-F]+))?/i.exec(part.trim());
    if (!m) throw new Error(`bad unicode-range item: ${part}`);
    const lo = parseInt(m[1]!, 16);
    return [lo, m[2] ? parseInt(m[2], 16) : lo];
  });
const covers = (sp: Span[], cp: number): boolean => sp.some(([lo, hi]) => lo <= cp && cp <= hi);
const isCjk = (cp: number): boolean => (cp >= 0x4e00 && cp <= 0x9fff) || (cp >= 0x3400 && cp <= 0x4dbf) || (cp >= 0xf900 && cp <= 0xfaff);
const glyphs = (cps: Iterable<number>): string => Array.from(cps, (cp) => String.fromCodePoint(cp)).join('');

/* ── the UI glyph inventory, mirrored from UI_SOURCES / UI_EXCLUDE in scripts/fonts/build-fonts.py ── */
const UI_EXCLUDE = ['.test.', 'src/content/fixtures/', 'src/art/wallpapers/kanji-stars.ts'];

function walk(dir: string, out: string[] = []): string[] {
  for (const name of readdirSync(dir)) {
    if (name === 'node_modules' || name.startsWith('.')) continue;
    const full = join(dir, name);
    if (statSync(full).isDirectory()) walk(full, out);
    else out.push(full);
  }
  return out;
}

const uiFiles = [...walk(resolve(ROOT, 'src')).filter((p) => /\.(ts|tsx|css)$/.test(p)), resolve(ROOT, 'index.html'), resolve(ROOT, 'public/manifest.webmanifest')].filter(
  (p) => !UI_EXCLUDE.some((x) => relative(ROOT, p).split(sep).join('/').includes(x)),
);
const uiKanji = new Set<number>();
for (const p of uiFiles) {
  for (const ch of readFileSync(p, 'utf8')) {
    const cp = ch.codePointAt(0)!;
    if (isCjk(cp)) uiKanji.add(cp);
  }
}

describe('fonts.css slices', () => {
  it('declares the four families, each with base + the four JLPT level slices', () => {
    for (const family of FAMILIES) {
      const slices = byFamily(family).map((f) => slice(f.file));
      expect(slices, family).toEqual(expect.arrayContaining(['base', 'n5', 'n4', 'n3', 'n2']));
    }
  });

  it('the brush family (Yuji Syuku) ships no catch-all `rest` face: shell chrome and proper names never pull 815 KB of non-corpus kanji', () => {
    const yuji = byFamily('Yuji Syuku');
    expect(yuji.some((f) => slice(f.file) === 'rest')).toBe(false);
    expect(yuji.some((f) => f.range.includes('U+4E00-9FFF'))).toBe(false);
  });

  it('where a `rest` face exists it is declared first (lowest precedence) and the level slices use explicit code points', () => {
    for (const family of ['DotGothic16', 'Shippori Mincho B1', 'Dela Gothic One']) {
      const list = byFamily(family);
      expect(slice(list[0]!.file), family).toBe('rest');
      expect(slice(list[list.length - 1]!.file), family).toBe('base');
      for (const f of list.filter(isLevel)) expect(f.range, f.file).not.toMatch(/U\+4E00-9FFF/);
    }
  });

  it('`base` is declared last in every family and lists its code points explicitly beyond the kana / symbol blocks', () => {
    for (const family of FAMILIES) {
      const list = byFamily(family);
      const base = list[list.length - 1]!;
      expect(slice(base.file), family).toBe('base');
      expect(base.range, family).toMatch(/U\+3000-30FF/); // kana and CJK punctuation stay a block range
      expect(spans(base.range).filter(([lo]) => isCjk(lo)).length, family).toBeGreaterThan(100);
    }
  });

  it('the UI glyph inventory (every CJK ideograph in src/**, index.html and the manifest) sits in every family\'s `base` face and in no level slice', () => {
    expect(uiKanji.size).toBeGreaterThan(300); // strings files, STATIONS, belt / page / reward names
    for (const family of FAMILIES) {
      const list = byFamily(family);
      const base = spans(list[list.length - 1]!.range);
      const missing = [...uiKanji].filter((cp) => !covers(base, cp));
      expect(glyphs(missing), `${family} base lacks shell glyphs — rerun scripts/fonts/build-fonts.py`).toBe('');
      for (const f of list.filter(isLevel)) {
        const level = spans(f.range);
        const leaked = [...uiKanji].filter((cp) => covers(level, cp));
        expect(glyphs(leaked), `${f.file} still carries shell glyphs — rerun scripts/fonts/build-fonts.py`).toBe('');
      }
    }
  });

  it('station names (STATIONS) and the nav glyphs 橋帯庫蔵録設 render from `base` alone', () => {
    const must = new Set<number>();
    for (const ch of ['橋帯庫蔵録設', ...STATIONS.flatMap((s) => [s.nameJa, s.gateJa])].join('')) {
      const cp = ch.codePointAt(0)!;
      if (isCjk(cp)) must.add(cp);
    }
    expect(must.has('鞠'.codePointAt(0)!)).toBe(true); // 鞠子 — a non-JLPT kanji that used to live in `rest`
    for (const family of FAMILIES) {
      const list = byFamily(family);
      const base = spans(list[list.length - 1]!.range);
      expect(glyphs([...must].filter((cp) => !covers(base, cp))), family).toBe('');
    }
  });

  it('every face has a local() fallback, format("woff2"), font-display: swap, and its slice file ships in public/fonts/', () => {
    const bodies = Array.from(css.matchAll(/@font-face \{([^}]*)\}/g), (m) => m[1]!);
    expect(bodies).toHaveLength(faces.length);
    for (const body of bodies) {
      expect(body).toMatch(/font-display: swap/);
      expect(body).toMatch(/src: local\("[^"]+"\), local\("[^"]+"\), url\("\/fonts\/[A-Za-z0-9]+-(rest|n2|n3|n4|n5|base)\.woff2"\) format\("woff2"\)/);
    }
    for (const f of faces) expect(() => statSync(resolve(ROOT, 'public/fonts', f.file)), f.file).not.toThrow();
  });

  it('no orphan slice on disk: every public/fonts/*.woff2 is referenced by fonts.css (the dropped Yuji `rest` is gone)', () => {
    const referenced = new Set(faces.map((f) => f.file));
    const onDisk = readdirSync(resolve(ROOT, 'public/fonts')).filter((f) => f.endsWith('.woff2'));
    expect(onDisk.filter((f) => !referenced.has(f))).toEqual([]);
    expect(onDisk).not.toContain('YujiSyuku-rest.woff2');
    for (const stem of ['DotGothic16', 'YujiSyuku', 'ShipporiMinchoB1', 'DelaGothicOne']) expect(onDisk, stem).toContain(`${stem}-base.woff2`);
  });
});
